        }
        let sum: Int = 0;
        loop c in 0..width {
            let h: Int = toon_int_value(toon_at(row, c));
            sum = sum + h;
            if h > peak {
                peak = h;
                peakRow = r;
            }
        }
        fx { println("row ", r, " sum ", sum); }
    }

    fx {
        println("peak ", peak, " at row ", peakRow);
