fn jsonQuote(raw: Text) -> Text {
    let ms: MStream = mstreamcreate();
    mstreamappendbyte(ms, ord("\""));
    loop ch in raw {
        let b: Int = ord(ch);
        if b == 34 {
            appendText(ms, "\\\"");
        } else if b == 92 {
            appendText(ms, "\\\\");
        } else if b == 10 {
            appendText(ms, "\\n");
        } else if b == 9 {
            appendText(ms, "\\t");
        } else {
            mstreamappendbyte(ms, b);
        }
    }
    mstreamappendbyte(ms, ord("\""));
    let quoted: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret quoted;
}

