fn rot13Byte(b: Int) -> Int {
    if b >= 65 && b <= 90 {
        ret (b - 65 + 13) % 26 + 65;
    }
    if b >= 97 && b <= 122 {
        ret (b - 97 + 13) % 26 + 97;
    }
    ret b;
}

