fn liveNeighbours(g: Bool[][], r: Int, c: Int) -> Int {
    let count: Int = 0;
    loop dr in -1..2 {
        loop dc in -1..2 {
            let y: Int = r + dr;
            let x: Int = c + dc;
            if (dr != 0 || dc != 0) && y >= 0 && y < length(g) && x >= 0 && x < length(g[y]) {
                if g[y][x] {
                    count = count + 1;
                }
            }
        }
    }
    ret count;
}

