    fx {
        loop slot in slots {
            if can[n][slot] {
                let picked: Text = "";
                let left: Int = slot;
                loop i in n..0 step -1 {
                    if !can[i - 1][left] {
                        if picked == "" {
                            picked = names[i - 1];
                        } else {
                            picked = names[i - 1] + " + " + picked;
                        }
                        left = left - minutes[i - 1];
                    }
                }
                println(slot, " min: ", picked);
            } else {
                println(slot, " min: no exact fill");
            }
        }
    }
    ret;
}

