@pure
fn firstOccurrences(tags: Text[]) -> Text[] {
    let kept: Text[] = [];
    loop tag in tags {
        let seen: Bool = false;
        loop k in kept {
            if k == tag {
                seen = true;
                break;
            }
        }
        if !seen {
            kept = kept + [tag];
        }
