fn properDivisorSum(n: Int) -> Int {
    if n < 2 {
        ret 0;
    }
    let total: Int = 1;
    let d: Int = 2;
    loop d * d <= n {
        if n % d == 0 {
            let partner: Int = n div d;
            total = total + d;
            if partner != d {
                total = total + partner;
            }
        }
        d = d + 1;
    }
    ret total;
}

