fn parseHex(s: Text) -> (Int, Int) {
    let value: Int = 0;
    loop i in 0..string_len(s) {
        let c: Int = ord(s[i]);
        let digit: Int = -1;
        if c >= ord("0") && c <= ord("9") {
            digit = c - ord("0");
        } else if c >= ord("a") && c <= ord("f") {
            digit = c - ord("a") + 10;
        } else if c >= ord("A") && c <= ord("F") {
            digit = c - ord("A") + 10;
        } else {
            ret (0, i);
        }
        value = value * 16 + digit;
    }
    ret (value, -1);
}

