                if c < cols - 1 && grid[r][c + 1] == 1 {
                    neighbors = neighbors + 1;
                }
                if neighbors >= 2 {
                    rowCrowded[r] = rowCrowded[r] + 1;
                    totalCrowded = totalCrowded + 1;
                }
            }
        }
    }

    let notCrowded: Int = totalOccupied - totalCrowded;
    let busiestRow: Int = 1;
    let maxOccupied: Int = rowOccupied[0];
    loop r in 1..rows {
        if rowOccupied[r] > maxOccupied {
            maxOccupied = rowOccupied[r];
            busiestRow = r + 1;
        }
    }

    fx {
        println("Row 1 crowded: ", rowCrowded[0]);
        println("Row 2 crowded: ", rowCrowded[1]);
        println("Row 3 crowded: ", rowCrowded[2]);
        println("Total crowded: ", totalCrowded);
        println("Occupied not crowded: ", notCrowded);
        println("Busiest row: ", busiestRow);
    }
    ret;
}

fn main() -> Void {
