    ];

    loop pass in 0..4 {
        let next: Int[][] = [];
        loop r in 0..4 {
            let row: Int[] = [];
            loop c in 0..4 {
                let v: Int = grid[r][c];
                if v >= 3 {
                    row = row + [v - 1];
                } else {
                    row = row + [v];
                }
            }
            next = next + [row];
        }
        grid = next;
    }

    let soggy: Int = 0;
