            }
            total = total + v;
            if c > 0 {
                fx { print(" "); }
            }
            fx { print(v); }
        }
        fx { println(""); }
    }

    fx {
        println("Soggy after: ", soggy);
        println("Total sum: ", total);
    }

    ret;
}

