@pure
fn isPrime(n: Int) -> Bool {
    if n < 2 {
        ret false;
    }
    if n == 2 {
        ret true;
    }
    if n % 2 == 0 {
        ret false;
    }
    let d: Int = 3;
    loop d * d <= n {
        if n % d == 0 {
            ret false;
        }
        d = d + 2;
    }
    ret true;
}

@pure
fn isIncreasing(n: Int) -> Bool {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    if len <= 1 {
        ret true;
    }
    loop i in 1..len {
        if ord(s[i]) <= ord(s[i - 1]) {
            ret false;
        }
    }
    ret true;
}

