@pure
fn countDivisors(n: Int) -> Int {
    let count: Int = 0;
    loop i in 1..n + 1 {
        if n % i == 0 {
            count = count + 1;
        }
    }
    ret count;
}

@pure
fn isPerfectSquare(n: Int) -> Bool {
    if n < 0 {
        ret false;
    }
    let r: Int = int(sqrt(real(n)));
    ret r * r == n;
}

