fn main() -> Void {
    let arrive: Int[] = [0, 5, 10, 25, 45];
    let dry: Int[] = [40, 30, 50, 20, 35];
    let free1: Int = 0;
    let free2: Int = 0;

    loop i in 0..length(arrive) {
        let a: Int = arrive[i];
        let d: Int = dry[i];
        let dryer: Int = 0;
        let start: Int = 0;
        let finish: Int = 0;

        if a >= free1 {
            dryer = 1;
            start = a;
            finish = a + d;
            free1 = finish;
        } else if a >= free2 {
            dryer = 2;
            start = a;
            finish = a + d;
            free2 = finish;
        } else {
            if free1 <= free2 {
                dryer = 1;
                start = free1;
                finish = free1 + d;
                free1 = finish;
            } else {
                dryer = 2;
                start = free2;
                finish = free2 + d;
                free2 = finish;
            }
        }

        fx {
            println("Load ", i + 1, " dryer ", dryer, " start ", start, " finish ", finish);
        }
    }

    ret;
}

