            print(colBlockages[i]);
        }
        println("");
        if length(clearRows) == 0 {
            println("Clear Rows: none");
        } else {
            print("Clear Rows: ");
            loop i in 0..length(clearRows) {
                if i > 0 {
                    print(" ");
                }
                print(clearRows[i]);
            }
            println("");
        }
    }
    ret;
