    let state: Int = 0;

    loop i in 0..length(scores) {
        let s: Int = scores[i];
        let target: Int = 0;
        if s <= 3 {
            target = 0;
        } else if s <= 7 {
            target = 1;
        } else {
            target = 2;
        }

        if target > state {
            if target - state > 1 {
                state = state + 1;
            } else {
                state = target;
            }
        } else {
            state = target;
        }

        let label: Text = "CALM";
        if state == 1 {
            label = "BUSY";
        } else if state == 2 {
            label = "RUSH";
        }

        fx {
            println("O", i + 1, " Score=", s, " State=", label);
        }
    }

    ret;
}

