fn main() -> Void {
    let names: Text[] = ["Alice", "Bob", "Carol", "Dave"];
    let scores: Int[][] = [
        [78, 92, 85, 85, 91],
        [64, 77, 85, 70, 66],
        [95, 88, 90, 92, 87],
        [77, 85, 71, 85, 80]
    ];

    let totals: Int[] = [];
    loop i in 0..length(names) {
        let sum: Int = 0;
        loop j in 0..length(scores[i]) {
            sum = sum + scores[i][j];
        }
        totals = totals + [sum];
    }

    let order: Int[] = [0, 1, 2, 3];
    loop i in 1..length(order) {
        let v: Int = order[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if totals[order[j]] > totals[v] {
                break;
            }
            if totals[order[j]] == totals[v] {
                if names[order[j]] <= names[v] {
                    break;
                }
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = v;
    }

    let rank: Int = 1;
    let prevTotal: Int = -1;
    loop i in 0..length(order) {
        let idx: Int = order[i];
        if i > 0 && totals[idx] != prevTotal {
            rank = i + 1;
        }
        prevTotal = totals[idx];
        fx {
            println(rank, " ", names[idx], " ", totals[idx]);
        }
    }

    ret;
}

