@pure
fn sorted(xs: Int[]) -> Int[] {
    let out: Int[] = xs;
    loop i in 1..length(out) {
        let v: Int = out[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if out[j] <= v {
                break;
            }
            out[j + 1] = out[j];
            j = j - 1;
        }
        out[j + 1] = v;
    }
    ret out;
}

