@pure
fn isValidLabel(label: Text) -> Bool {
    if string_len(label) != 6 {
        ret false;
    }
    if !isUpper(label[0]) {
        ret false;
    }
    if !isUpper(label[1]) {
        ret false;
    }
    if label[2] != "-" {
        ret false;
    }
    if !isDigit(label[3]) {
        ret false;
    }
    if !isDigit(label[4]) {
        ret false;
    }
    if !isDigit(label[5]) {
        ret false;
    }
    ret true;
}

