@pure
fn isValidCode(code: Text) -> Bool {
    if string_len(code) != 7 {
        ret false;
    }
    if !isUpperLetter(code[0]) {
        ret false;
    }
    if !isUpperLetter(code[1]) {
        ret false;
    }
    if code[2] != "-" {
        ret false;
    }
    if !isDigit(code[3]) {
        ret false;
    }
    if !isDigit(code[4]) {
        ret false;
    }
    if !isDigit(code[5]) {
        ret false;
    }
    if !isUpperLetter(code[6]) {
        ret false;
    }
    ret true;
}

