@pure
fn isDigit(c: Text) -> Bool {
    let code: Int = ord(c);
    ret code >= 48 && code <= 57;
}

@pure
fn isUpper(c: Text) -> Bool {
    let code: Int = ord(c);
    ret code >= 65 && code <= 90;
}

@pure
fn isValidBarcode(code: Text) -> Bool {
    if string_len(code) != 7 {
        ret false;
    }
    if code[4] != "-" {
        ret false;
    }
    loop i in 0..4 {
        if !isDigit(code[i]) {
            ret false;
        }
    }
    if !isUpper(code[5]) {
        ret false;
    }
    if !isUpper(code[6]) {
        ret false;
    }
    ret true;
}

