    let curRun: Int = 1;
    loop i in 1..n {
        if prices[i] == prices[i - 1] {
            curRun = curRun + 1;
        } else {
            curRun = 1;
        }
        if curRun > longestRun {
            longestRun = curRun;
        }
    }

    let first5: Int = -1;
