fn main() -> Void {
    let temps: Int[][] = [
        [-2, -1, 0, 1, 2],
        [-1, -3, -2, 0, 1],
        [0, -2, -4, -1, 0],
        [1, 0, -1, -2, 1],
        [2, 1, 0, 1, 2]
    ];

    let rows: Int = length(temps);
    let cols: Int = length(temps[0]);

    let frost: Int = 0;
    let core: Int = 0;
    let isolated: Int = 0;

    loop r in 0..rows {
        loop c in 0..cols {
            let v: Int = temps[r][c];
            if v < 0 {
                frost = frost + 1;
            }
            if v < -2 {
                core = core + 1;
                let isIso: Bool = true;
                if r > 0 && temps[r - 1][c] < -2 {
                    isIso = false;
                }
                if r < rows - 1 && temps[r + 1][c] < -2 {
                    isIso = false;
                }
                if c > 0 && temps[r][c - 1] < -2 {
                    isIso = false;
                }
                if c < cols - 1 && temps[r][c + 1] < -2 {
                    isIso = false;
                }
                if isIso {
                    isolated = isolated + 1;
                }
            }
        }
    }

    let ratio: Real = 0.0;
    if frost > 0 {
        ratio = core * 1.0 / frost;
    }

    fx {
        println("FROST ", frost);
        println("CORE ", core);
        println("ISOLATED ", isolated);
        println("RATIO ", formatfloat(ratio, 3));
    }

    ret;
}

fn main() -> Void {
    let stock: Int[][] = [
        [5, 3, 7, 2],
        [8, 0, 4, 6],
        [1, 9, 2, 5],
        [7, 3, 8, 1]
    ];

    let order: Int[] = [];
    let top: Int = 0;
    let bottom: Int = 3;
    let left: Int = 0;
    let right: Int = 3;

    loop {
        loop c in left..right + 1 {
            order = order + [stock[top][c]];
        }
        top = top + 1;
        if top > bottom {
            break;
        }

        loop r in top..bottom + 1 {
            order = order + [stock[r][right]];
        }
        right = right - 1;
        if left > right {
            break;
        }

        loop c in right..left - 1 step -1 {
            order = order + [stock[bottom][c]];
        }
        bottom = bottom - 1;
        if top > bottom {
            break;
        }

        loop r in bottom..top - 1 step -1 {
            order = order + [stock[r][left]];
        }
        left = left + 1;
        if left > right {
            break;
        }
    }

    let total: Int = 0;
    loop i in 0..length(order) {
        total = total + order[i];
    }

    let maxdrop: Int = 0;
    loop i in 0..length(order) - 1 {
        let drop: Int = order[i] - order[i + 1];
        if drop > maxdrop {
            maxdrop = drop;
        }
    }

    fx {
        print("ORDER");
        loop i in 0..length(order) {
            print(" ", order[i]);
        }
        println("");
        println("TOTAL ", total);
        println("MAXDROP ", maxdrop);
    }
    ret;
}

