@pure
fn isUpperLetter(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 65 && c <= 90;
}

@pure
fn isDigit(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 48 && c <= 57;
}

@pure
fn bibStatus(bib: Text) -> Text {
    if string_len(bib) != 6 {
        ret "BAD";
    }
    if !isUpperLetter(bib[0]) || !isUpperLetter(bib[1]) {
        ret "BAD";
    }
    if !isDigit(bib[2]) || !isDigit(bib[3]) || !isDigit(bib[4]) || !isDigit(bib[5]) {
        ret "BAD";
    }
    ret "OK";
}

