    loop i in 0..length(labels) {
        let label: Text = labels[i];
        let fruit: Text = label[0];
        let valid: Bool = false;
        if string_len(label) == 5 {
            let c0: Int = ord(label[0]);
            if c0 >= 65 && c0 <= 90 {
                let allDigits: Bool = true;
                loop j in 1..5 {
                    let cj: Int = ord(label[j]);
                    if cj < 48 || cj > 57 {
                        allDigits = false;
                        break;
