@pure
fn isUpperLetter(c: Text) -> Bool {
    let code: Int = ord(c);
    ret code >= 65 && code <= 90;
}

@pure
fn isDigit(c: Text) -> Bool {
    let code: Int = ord(c);
    ret code >= 48 && code <= 57;
}

@pure
fn isWellFormed(code: Text) -> Bool {
    if string_len(code) != 7 {
        ret false;
    }
    if !isUpperLetter(code[0]) {
        ret false;
    }
    if !isUpperLetter(code[1]) {
        ret false;
    }
    if code[2] != "-" {
        ret false;
    }
    if !isDigit(code[3]) {
        ret false;
    }
    if !isDigit(code[4]) {
        ret false;
    }
    if !isDigit(code[5]) {
        ret false;
    }
    if !isDigit(code[6]) {
        ret false;
    }
    ret true;
}

