@pure
fn isValidCode(code: Text) -> Bool {
    if string_len(code) != 3 {
        ret false;
    }
    loop i in 0..3 {
        let c: Int = ord(code[i]);
        if c < 65 || c > 90 {
            ret false;
        }
    }
    ret true;
}

