                row = row - 1;
            } else {
                col = col + 1;
            }
            if row < 0 {
                row = 0;
            }
            if row > 4 {
                row = 4;
            }
            if col < 0 {
                col = 0;
            }
            if col > 4 {
                col = 4;
            }
        } else if c == "L" {
            dir = (dir + 3) % 4;
        } else if c == "R" {
            dir = (dir + 1) % 4;
        }
    }

    let dirName: Text = "North";
