fn main() -> Void {
    let count: Int = 0;
    // Day 1 is always C, so we only iterate days 2-5
    // Each day is 0 (C) or 1 (F)
    loop d2 in 0..2 {
        loop d3 in 0..2 {
            loop d4 in 0..2 {
                loop d5 in 0..2 {
                    // Day 1 = C (0), so total F count = d2 + d3 + d4 + d5
                    let foggy: Int = d2 + d3 + d4 + d5;
                    if foggy == 2 {
                        // Check adjacency: no two consecutive F days
                        // Days: 1(C), 2(d2), 3(d3), 4(d4), 5(d5)
                        let adj: Bool = false;
                        if d2 == 1 && d3 == 1 {
                            adj = true;
                        }
                        if d3 == 1 && d4 == 1 {
                            adj = true;
                        }
                        if d4 == 1 && d5 == 1 {
                            adj = true;
                        }
                        if !adj {
                            let s: Text = "C";
                            if d2 == 1 {
                                s = s + "F";
                            } else {
                                s = s + "C";
                            }
                            if d3 == 1 {
                                s = s + "F";
