fn countTag(tags: Text[], cat: Text) -> Int {
    let total: Int = 0;
    loop i in 0..length(tags) { if tags[i] == cat { total = total + 1; } }
    ret total;
}

fn main() -> Void {
    let items: Text[] = ["bean", "duck", "wheat", "wheat", "bean", "bean", "beef", "ham", "lamb"];
