    fx {
        println("Fibonacci Spiral (first 10):");
        println("----------------------------");
    }
    loop i in 0..limit {
        let val: Int = fib(i);
        let line: Text = make_row(limit, val);
        fx { println(line); }
    }
    fx { println("----------------------------"); println("Done."); }
    ret;
}

@pure
fn classify_status(code: Int) -> Text {
