// Log-line parsing with split, trim, pos, copy

@pure
fn levelOf(line: Text) -> Text {
    let parts: Text[] = split(line, "|");
    if length(parts) < 2 { ret "UNKNOWN"; }
    ret trim(parts[0]);
}

@pure
fn messageOf(line: Text) -> Text {
    let at: Int = pos("|", line);
    if at < 0 { ret line; }
    ret trim(copy(line, at + 1, string_len(line) - at - 1));
}

