// A typed ledger — record defaults, methods, pointer-backed mutation

type Account {
    owner: Text = "";
    balance: Int = 0;
    overdrafts: Int = 0;

    fn deposit(amount: Int) -> Void {
        self.balance = self.balance + amount;
        ret;
    }

    @pre amount > 0
    fn withdraw(amount: Int) -> Bool {
        if amount > self.balance { self.overdrafts = self.overdrafts + 1; ret false; }
        self.balance = self.balance - amount;
        ret true;
    }

    fn status() -> Text {
        if self.balance >= 10000 { ret "premium"; }
        if self.balance >= 0 { ret "standard"; }
        ret "frozen";
    }
}

