fn collatzLength(n: Int) -> Int {
    let steps: Int = 0;
    let current: Int = n;
    loop current != 1 {
        if current % 2 == 0 {
            current = current / 2;
        } else {
            current = current * 3 + 1;
        }
        steps = steps + 1;
    }
    ret steps;
}

fn main() -> Void {
